-- | Whether a syntax kind is trivia (@%trivia@).
isTriviaSyntaxKind :: PegRt.SyntaxKind -> PegPrelude.Bool
isTriviaSyntaxKind peg'k = PegPrelude.elem peg'k [syntaxKindWs, syntaxKindInd, syntaxKindComment]

-- | A node of the rule @File@.
newtype FileSyntax = FileSyntax PegRt.SyntaxNode
  deriving (PegPrelude.Eq, PegPrelude.Show)

-- | The node, if it is a node of the rule @File@.
castFileSyntax :: PegRt.SyntaxNode -> PegPrelude.Maybe FileSyntax
castFileSyntax peg'n =
  if PegRt.syntaxKind peg'n PegPrelude.== syntaxKindFile then PegPrelude.Just (FileSyntax peg'n) else PegPrelude.Nothing

